//
//  ErrorCodeTests.swift
//  blindpay-swift
//
//  ErrorCode.swift is generated by check-contract.swift from the snapshot's
//  error table. These tests compare it with the shared oracle
//  (Vectors/error-codes.json, a copy of sdk-parity reference/error-codes.json)
//  and prove check-contract fails when the spec gains a code or loses the table.
//

import Foundation
import Testing
@testable import BlindPay

private struct OracleFile: Decodable {
    struct Row: Decodable { let code: String; let status: Int; let retry: String }
    let count: Int
    let codes: [Row]
}

private let oracle: OracleFile = {
    let url = Bundle.module.url(forResource: "Vectors/error-codes", withExtension: "json")
        ?? Bundle.module.url(forResource: "error-codes", withExtension: "json", subdirectory: "Vectors")!
    return try! JSONDecoder().decode(OracleFile.self, from: Data(contentsOf: url))
}()

struct ErrorCodeTests {
    @Test func everyDocumentedCodeHasItsStatusAndRetryClass() {
        #expect(oracle.codes.count == oracle.count)
        #expect(ErrorCode.table.count == oracle.count)
        for row in oracle.codes {
            let info = ErrorCode(rawValue: row.code).info
            #expect(info == ErrorCodeInfo(status: row.status, retry: RetryClass(rawValue: row.retry)), "\(row.code)")
        }
        let classes = Dictionary(grouping: ErrorCode.table.values, by: \.retry).mapValues(\.count)
        #expect(classes[.actionable] == 96)
        #expect(classes[.terminal] == 61)
        #expect(classes[.retryable] == 18)
    }

    @Test func anAPIErrorExposesItsTypedCodeAndRetryClass() {
        let error = APIError(status: 400, code: "TRANSFERS_SWAP_AMOUNT_BELOW_MINIMUM", message: "fx_amount_below_minimum")
        #expect(error.errorCode == .transfersSwapAmountBelowMinimum)
        #expect(error.retryClass == .actionable)
        #expect(error.errorCode?.info?.status == 400)
        // `code` stays the plain string.
        #expect(error.code == ErrorCode.transfersSwapAmountBelowMinimum.rawValue)
    }

    @Test func theReadmeSwitchCompilesAndMatches() {
        func reaction(_ error: APIError) -> String {
            switch error.errorCode {
            case .transfersSwapAmountBelowMinimum?: return "raise"
            case .quotesExpired?: return "requote"
            default: return error.retryClass == .actionable ? "fix" : "other"
            }
        }
        #expect(reaction(APIError(status: 400, code: "TRANSFERS_SWAP_AMOUNT_BELOW_MINIMUM", message: "fx_amount_below_minimum")) == "raise")
        #expect(reaction(APIError(status: 400, code: "QUOTES_EXPIRED", message: "quote_expired")) == "requote")
        #expect(reaction(APIError(status: 400, code: "PAYOUTS_INSUFFICIENT_BALANCE", message: "x")) == "fix")
        #expect(reaction(APIError(status: 409, message: "idempotency_key_in_flight")) == "other")
    }

    @Test func unknownAndMissingCodesStayOpen() {
        let unknown = APIError(status: 400, code: "SOMETHING_NEW", message: "x")
        #expect(unknown.errorCode?.rawValue == "SOMETHING_NEW")
        #expect(unknown.errorCode?.info == nil)
        #expect(unknown.retryClass == .unknown)

        let none = APIError(status: 409, message: "idempotency_key_in_flight")
        #expect(none.errorCode == nil)
        #expect(none.retryClass == .unknown)
    }

    @Test func aDecodedErrorBodyMatchesByCode() async throws {
        let body = #"{"success":false,"code":"AUTH_RATE_LIMITED","message":"fx_quote_rate_limit_exceeded","description":"Too many requests.","errors":["Limit is 300 requests per 60s. Try again in 12s."]}"#
        let server = MockServer(respondWith: .status(429, retryAfter: "12", body: body))
        let response = try await server.client(maxRetries: 0).instances.quotes.getFxRate(
            data: GetFxRateInput(currencyType: .sender, from: .usdc, to: .brl, requestAmount: 1000))
        let error = try #require(response.error)
        #expect(error.errorCode == .authRateLimited)
        #expect(error.retryClass == .retryable)
        #expect(error.message == "fx_quote_rate_limit_exceeded")
    }
}

// MARK: - check-contract's error-code gate

private let packageRoot = URL(fileURLWithPath: #filePath)
    .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent().path

private func runCheckContract(snapshot: String) -> (code: Int32, output: String) {
    let process = Process()
    process.executableURL = URL(fileURLWithPath: "/usr/bin/env")
    process.arguments = ["swift", ".api-sync/check-contract.swift", "--snapshot", snapshot]
    process.currentDirectoryURL = URL(fileURLWithPath: packageRoot)
    let pipe = Pipe()
    process.standardOutput = pipe
    process.standardError = pipe
    try! process.run()
    let data = pipe.fileHandleForReading.readDataToEndOfFile()
    process.waitUntilExit()
    return (process.terminationStatus, String(decoding: data, as: UTF8.self))
}

/// Writes a copy of the committed snapshot with its Errors tag description
/// transformed, and returns the copy's path.
private func snapshotCopy(_ transform: (String) -> String) throws -> String {
    let data = try Data(contentsOf: URL(fileURLWithPath: packageRoot + "/.api-sync/spec-snapshot.json"))
    var spec = try #require(try JSONSerialization.jsonObject(with: data) as? [String: Any])
    var tags = try #require(spec["tags"] as? [[String: Any]])
    let index = try #require(tags.firstIndex { $0["name"] as? String == "Errors" })
    tags[index]["description"] = transform(try #require(tags[index]["description"] as? String))
    spec["tags"] = tags
    let path = FileManager.default.temporaryDirectory.appendingPathComponent("snapshot-\(UUID().uuidString).json").path
    try JSONSerialization.data(withJSONObject: spec).write(to: URL(fileURLWithPath: path))
    return path
}

@Suite(.serialized)
struct ErrorCodeGateTests {
    @Test func aNewCodeInTheSpecFailsTheCheck() throws {
        let path = try snapshotCopy { $0 + "\n| `ZZ_FUTURE_CODE` | 400 | terminal | A code the SDK doesn't list yet. |\n" }
        let result = runCheckContract(snapshot: path)
        #expect(result.code == 1)
        #expect(result.output.contains("ZZ_FUTURE_CODE"))
        #expect(result.output.contains("--write-error-codes"))
    }

    @Test func aMissingErrorTableFailsTheCheck() throws {
        let path = try snapshotCopy { _ in "No table here." }
        let result = runCheckContract(snapshot: path)
        #expect(result.code == 1)
        #expect(result.output.contains("no error-code rows"))
    }
}
